#' Check if a file is generated by biocroxytest
#'
#' Require both a generated test filename and an exact ownership header.
#' Ordinary tests can also be adopted from roxytest. Symbolic links are never
#' treated as generated files.
#'
#' @param path A character string representing the path of the file to check.
#' @param suite The test suite, either `"tests"` or `"longtests"`.
#' @return TRUE for a generated file, FALSE otherwise.
#' @keywords internal
made_by_biocroxytest <- function(path, suite = "longtests") {
  pattern <- if (suite == "tests") "^test-roxytest-tests-" else "^test-biocroxytest-"
  if (!grepl(paste0(pattern, ".*[.][Rr]$"), basename(path))) { return(FALSE) }
  if (!file.exists(path) || dir.exists(path) || is_symlink(path)) { return(FALSE) }
  headers <- if (suite == "tests") c(generated_test_header, roxytest_header) else {
    generated_test_header
  }
  # The marker is ASCII. Compare bytes so a locale conversion cannot truncate
  # a manual header into an exact match.
  bom <- as.raw(c(239L, 187L, 191L))
  bytes <- readBin(path, "raw", n = max(nchar(headers, type = "bytes")) + 5L)
  if (identical(bytes[seq_len(3L)], bom)) { bytes <- bytes[-seq_along(bom)] }
  newline <- match(as.raw(10L), bytes)
  if (!is.na(newline)) {
    bytes <- bytes[seq_len(newline - 1L)]
    if (length(bytes) && bytes[length(bytes)] == as.raw(13L)) {
      bytes <- bytes[-length(bytes)]
    }
  }
  any(vapply(headers, function(header) identical(bytes, charToRaw(header)), logical(1)))
}

generated_test_header <- "# Generated by biocroxytest: do not edit by hand!"
roxytest_header <- "# Generated by roxytest: do not edit by hand!"

is_symlink <- function(path) {
  target <- Sys.readlink(path)
  !is.na(target) & nzchar(target)
}
